begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temp table ca_fx(k text primary key,id uuid,v jsonb);grant all on ca_fx to authenticated,service_role;
insert into ca_fx(k,id)select k,gen_random_uuid()from unnest(array['actor','other','session','job','transcribe','generate','retry_job','first','retry','retire_job','retire_attempt'])k;
create function pg_temp.ca_id(key text)returns uuid language sql as $$select id from ca_fx where k=$1$$;
insert into auth.users(id,email,raw_user_meta_data)select id,'synthetic-audio-'||id||'@example.test','{}'from ca_fx where k in('actor','other');
update profiles set is_active=true,full_name='Synthetic audio staff'where id in(pg_temp.ca_id('actor'),pg_temp.ca_id('other'));
insert into user_roles(user_id,role)values(pg_temp.ca_id('actor'),'STAFF'),(pg_temp.ca_id('other'),'STAFF')on conflict do nothing;
insert into auth.sessions(id,user_id,created_at,updated_at)values(pg_temp.ca_id('session'),pg_temp.ca_id('actor'),now(),now());
select ok(relrowsecurity and not has_table_privilege('authenticated',oid,'SELECT')and not has_table_privilege('authenticated',oid,'INSERT')and not has_table_privilege('service_role',oid,'SELECT'),relname||' private')from pg_class where relnamespace='public'::regnamespace and relname in('clinical_audio_policies','clinical_audio_jobs','clinical_audio_attempts','clinical_audio_events','clinical_audio_generations');
select ok(has_function_privilege('authenticated',oid,'EXECUTE')and not has_function_privilege('anon',oid,'EXECUTE')and not has_function_privilege('service_role',oid,'EXECUTE'),proname||' guarded staff only')from pg_proc where pronamespace='public'::regnamespace and proname in('read_clinical_audio','read_clinical_audio_job','read_clinical_audio_provenance','reserve_clinical_audio','claim_clinical_audio');
select ok(has_function_privilege('service_role',oid,'EXECUTE')and not has_function_privilege('anon',oid,'EXECUTE')and not has_function_privilege('authenticated',oid,'EXECUTE'),proname||' scoped worker only')from pg_proc where pronamespace='public'::regnamespace and proname in('dispatch_clinical_audio','finish_clinical_audio','fail_clinical_audio');
select ok(not has_function_privilege('service_role',oid,'EXECUTE')and not has_function_privilege('anon',oid,'EXECUTE')and not has_function_privilege('authenticated',oid,'EXECUTE'),proname||' owner only')from pg_proc where pronamespace='public'::regnamespace and proname in('clinical_audio_current_policy','clinical_audio_policy_guard','clinical_audio_worker_actor','clinical_audio_job_view','clinical_audio_row_guard');
select is((select status from clinical_audio_policies where version=1),'draft','Policy defaults inactive');
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',pg_temp.ca_id('actor'),'session_id',pg_temp.ca_id('session'))::text,true);
set local role authenticated;
insert into ca_fx(k,id)select 'client',id from save_client(auth.uid(),null,null,'Synthetic','Audio','+13035555580','synthetic-audio@example.test','EMAIL',null,null);
insert into ca_fx(k,id)select 'pet',id from save_patient(null,pg_temp.ca_id('client'),null,'Synthetic Audio','Dog','Mixed',null,'unknown','','unknown','unknown','',null,null);
insert into ca_fx(k,id)select 'encounter',id from save_clinical_encounter(null,pg_temp.ca_id('pet'),null,now(),'clinic','Synthetic clinic','Original history','Original exam','Original assessment','Original plan');
insert into ca_fx(k,v)values('claims','{"subjective":[{"text":"Cough for two days.","quote":"cough for two days"}],"objective":[],"assessment":[],"plan":[],"review_flags":["No exam was dictated."]}');
insert into ca_fx(k,v)select 'request',jsonb_build_object('pet_id',pg_temp.ca_id('pet'),'encounter_id',pg_temp.ca_id('encounter'),'expected_version',1,'policy_version',1,'sha256',repeat('a',64),'frames',16000,'byte_size',32044,'source_note','Synthetic authorized clinician dictation','attest_authorized',true);
select throws_ok($$select reserve_clinical_audio(auth.uid(),pg_temp.ca_id('job'),(select v from ca_fx where k='request'))$$,'42501',null,'Draft policy cannot be overridden by attestation');
select throws_ok($$select read_clinical_audio(pg_temp.ca_id('other'),pg_temp.ca_id('pet'),pg_temp.ca_id('encounter'))$$,'42501',null,'Actor spoof rejected');
reset role;
insert into clinical_audio_policies(version,status,consent_text,audio_retention,transcript_retention,transcription_model,soap_model,reviewed_by,reviewed_at)values(2,'approved','Synthetic LOCAL TEST policy, not clinical approval','not_stored','Synthetic fixture retention','gpt-transcribe','gpt-6-luna',pg_temp.ca_id('actor'),now());
set local role authenticated;
update ca_fx set v=v||'{"policy_version":2}'where k='request';
select throws_ok($$select reserve_clinical_audio(auth.uid(),gen_random_uuid(),(select v||'{"unexpected":true}'from ca_fx where k='request'))$$,'23514',null,'Unknown source keys rejected');
select throws_ok($$select reserve_clinical_audio(auth.uid(),gen_random_uuid(),(select v||'{"frames":16001}'from ca_fx where k='request'))$$,'23514',null,'Byte/sample mismatch rejected');
select throws_ok($$select reserve_clinical_audio(auth.uid(),gen_random_uuid(),(select v||'{"attest_authorized":false}'from ca_fx where k='request'))$$,'23514',null,'Source authorization required');
insert into ca_fx(k,v)select 'reserved',reserve_clinical_audio(auth.uid(),pg_temp.ca_id('job'),(select v from ca_fx where k='request'));
select is(reserve_clinical_audio(auth.uid(),pg_temp.ca_id('job'),(select v from ca_fx where k='request')),(select v from ca_fx where k='reserved'),'Same source UUID recovers metadata');
select throws_ok($$select reserve_clinical_audio(auth.uid(),pg_temp.ca_id('job'),(select v||'{"source_note":"Changed"}'from ca_fx where k='request'))$$,'23505',null,'Changed source UUID reuse rejected');
select is(read_clinical_audio(auth.uid(),pg_temp.ca_id('pet'),pg_temp.ca_id('encounter'))#>>'{jobs,0,id}',pg_temp.ca_id('job')::text,'Read bound to saved encounter');
insert into ca_fx(k,v)select 'claimed',claim_clinical_audio(auth.uid(),pg_temp.ca_id('transcribe'),pg_temp.ca_id('job'),'transcribe');
select is(claim_clinical_audio(auth.uid(),pg_temp.ca_id('transcribe'),pg_temp.ca_id('job'),'transcribe'),(select v from ca_fx where k='claimed'),'Same attempt UUID recovers exact claim');
select throws_ok($$select claim_clinical_audio(auth.uid(),gen_random_uuid(),pg_temp.ca_id('job'),'transcribe',pg_temp.ca_id('transcribe'),'Retry',true)$$,'PT409',null,'Active lease cannot be superseded');
reset role;set local role service_role;
select is(dispatch_clinical_audio(pg_temp.ca_id('transcribe')),true,'One-shot dispatch admitted');
select is(dispatch_clinical_audio(pg_temp.ca_id('transcribe')),false,'Duplicate dispatch cannot call provider again');
insert into ca_fx(k,v)values('transcript_result','{"request_id":"synthetic-stt","response_id":"","provider_model":"","contract_version":"clinical-audio-v1","payload":{"text":"Owner reports cough for two days. No exam was dictated."}}');
select finish_clinical_audio(pg_temp.ca_id('transcribe'),(select v from ca_fx where k='transcript_result'));
select is(finish_clinical_audio(pg_temp.ca_id('transcribe'),(select v from ca_fx where k='transcript_result'))->>'transcript','Owner reports cough for two days. No exam was dictated.','Received result commit recovers without another provider call');
select throws_ok($$select finish_clinical_audio(pg_temp.ca_id('transcribe'),(select v||'{"request_id":"different"}'from ca_fx where k='transcript_result'))$$,'23505',null,'Completed result identity immutable');
reset role;set local role authenticated;
select is((select subjective from clinical_encounters where id=pg_temp.ca_id('encounter')),'Original history','Transcription leaves chart untouched');
select claim_clinical_audio(auth.uid(),pg_temp.ca_id('generate'),pg_temp.ca_id('job'),'generate');
reset role;set local role service_role;
select is(dispatch_clinical_audio(pg_temp.ca_id('generate')),true,'Generation has separate dispatch');
insert into ca_fx(k,v)select 'generation_result',jsonb_build_object('request_id','synthetic-gen','response_id','synthetic-response','provider_model','gpt-6-luna','contract_version','clinical-audio-v1','payload',(select v from ca_fx where k='claims'));
select throws_ok($$select finish_clinical_audio(pg_temp.ca_id('generate'),(select jsonb_set(v,'{payload,subjective,0,quote}','"unspoken normal"')from ca_fx where k='generation_result'))$$,'23514',null,'Every generated claim needs a resolving source quote');
select finish_clinical_audio(pg_temp.ca_id('generate'),(select v from ca_fx where k='generation_result'));
select is(finish_clinical_audio(pg_temp.ca_id('generate'),(select v from ca_fx where k='generation_result'))->>'proposal_id',pg_temp.ca_id('generate')::text,'Atomic proposal result recovers');
reset role;
select is((select count(*)from clinical_audio_generations),1::bigint,'One immutable generation');
select is((select count(*)from clinical_dictation_proposals where id=pg_temp.ca_id('generate')),1::bigint,'One linked proposal');
select is((select subjective from clinical_encounters where id=pg_temp.ca_id('encounter')),'Original history','Generation does not save chart');
select is((select actor_id from clinical_dictation_proposals where id=pg_temp.ca_id('generate')),pg_temp.ca_id('actor'),'Proposal attributed without impersonated worker session');
set local role authenticated;
select is(read_clinical_audio_provenance(auth.uid(),pg_temp.ca_id('generate'))->'payload',(select v from ca_fx where k='claims'),'Every claim and flag is retained for review');
select save_clinical_dictation_action(auth.uid(),gen_random_uuid(),'review',jsonb_build_object('pet_id',pg_temp.ca_id('pet'),'encounter_id',pg_temp.ca_id('encounter'),'expected_version',1,'proposal_id',pg_temp.ca_id('generate'),'decision','accepted','accepted_sections',jsonb_build_object('subjective','Reviewed cough history.'),'review_note','Reviewed generated source claims','attest_reviewed',true));
select is((select jsonb_build_array(subjective,objective,status)from clinical_encounters where id=pg_temp.ca_id('encounter')),'["Reviewed cough history.","Original exam","draft"]'::jsonb,'Existing review selectively saves and does not sign');
update ca_fx set v=v||'{"expected_version":2}'where k='request';
select reserve_clinical_audio(auth.uid(),pg_temp.ca_id('retry_job'),(select v from ca_fx where k='request'));
select claim_clinical_audio(auth.uid(),pg_temp.ca_id('first'),pg_temp.ca_id('retry_job'),'transcribe');
reset role;set local role service_role;
select dispatch_clinical_audio(pg_temp.ca_id('first'));
select fail_clinical_audio(pg_temp.ca_id('first'),true,'provider_outcome_unknown');
reset role;set local role authenticated;
select throws_ok($$select claim_clinical_audio(auth.uid(),pg_temp.ca_id('retry'),pg_temp.ca_id('retry_job'),'transcribe',pg_temp.ca_id('first'),'Retry',false)$$,'23514',null,'Uncertain retry requires possible-charge acknowledgement');
select claim_clinical_audio(auth.uid(),pg_temp.ca_id('retry'),pg_temp.ca_id('retry_job'),'transcribe',pg_temp.ca_id('first'),'Reviewed original unknown result; explicit synthetic retry',true);
reset role;set local role service_role;
select throws_ok($$select finish_clinical_audio(pg_temp.ca_id('first'),(select v from ca_fx where k='transcript_result'))$$,'PT409',null,'Superseded late result fenced out');
select dispatch_clinical_audio(pg_temp.ca_id('retry'));
select finish_clinical_audio(pg_temp.ca_id('retry'),(select v from ca_fx where k='transcript_result'));
reset role;
select is((select state from clinical_audio_attempts where id=pg_temp.ca_id('first')),'superseded','Old attempt history remains');
select throws_ok($$update clinical_audio_jobs set sha256=repeat('b',64)where id=pg_temp.ca_id('job')$$,'23514',null,'Source metadata immutable');
select throws_ok($$update clinical_audio_generations set payload='{}'$$,'23514',null,'Generated source history immutable');
select throws_ok($$delete from clinical_audio_events$$,'23514',null,'Transition history cannot be erased');
select throws_ok($$update clinical_audio_policies set consent_text='rewrite'where version=1$$,'23514',null,'Policy draft history immutable');
select is((select count(*)from storage.buckets where id='clinical-audio'),0::bigint,'No audio retention bucket created');
set local role authenticated;
select reserve_clinical_audio(auth.uid(),pg_temp.ca_id('retire_job'),(select v from ca_fx where k='request'));
select claim_clinical_audio(auth.uid(),pg_temp.ca_id('retire_attempt'),pg_temp.ca_id('retire_job'),'transcribe');
reset role;delete from auth.sessions where id=pg_temp.ca_id('session');
set local role service_role;
select throws_ok($$select dispatch_clinical_audio(pg_temp.ca_id('retire_attempt'))$$,'42501',null,'Revoked original session cannot dispatch paid work');
reset role;set local role authenticated;
select throws_ok($$select read_clinical_audio(auth.uid(),pg_temp.ca_id('pet'),pg_temp.ca_id('encounter'))$$,'42501',null,'Revoked session cannot read clinical audio history');
reset role;
select *from finish();rollback;
